import { isActionHiddenFromEveryAgentSurface } from "../action.js";
import { parseMcpToolName } from "../mcp-client/manager.js";
import { isMcpToolAllowedForRequest } from "../mcp-client/visibility.js";
import { getRequestRunContext } from "../server/request-context.js";
export const TOOL_SEARCH_ACTION_NAME = "tool-search";
const DEFAULT_LIMIT = 8;
const MAX_LIMIT = 25;
export function createToolSearchEntry(getRegistry, options = {}) {
    return {
        tool: {
            description: "Discover callable tools/actions, including connected MCP server tools named `mcp__<server>__<tool>`. Call it with NO query to list every available tool by name with a one-line description (cheap — no input schemas); names from that menu are not loaded for calling yet, so call tool-search again with a specific query for the tool/capability before invoking it. Use this whenever you need a capability but aren't sure which tool to call — most tools are not loaded into context up front, so this is how you find and then call them.",
            parameters: {
                type: "object",
                properties: {
                    query: {
                        type: "string",
                        description: "What capability to find, e.g. `send slack message`, `create calendar event`, `zapier gmail`, or `browser screenshot`. Omit to list every available tool name (the full menu) with one-line descriptions; then call tool-search again with a specific query before calling a tool from that menu.",
                    },
                    limit: {
                        type: "number",
                        description: `Maximum results to return for a query. Defaults to ${options.defaultLimit ?? DEFAULT_LIMIT}. Ignored when listing the full menu (no query).`,
                    },
                    includeSchemas: {
                        type: "boolean",
                        description: "When true, include each matching tool's full input schema. Default false.",
                    },
                    readOnlyOnly: {
                        type: "boolean",
                        description: "When true, return tools whose current policy is read-only or can classify the supplied arguments as read-only. The bounded orchestration host rechecks conditional policies before every call.",
                    },
                },
            },
        },
        http: false,
        readOnly: true,
        run: async (args) => searchToolRegistry(getRegistry(), args, options),
    };
}
export function attachToolSearch(registry, options = {}) {
    registry[TOOL_SEARCH_ACTION_NAME] = createToolSearchEntry(() => registry, options);
    return registry;
}
export function searchToolRegistry(registry, args = {}, options = {}) {
    const query = String(args.query ?? "").trim();
    // No query → "menu" mode: list every available tool by name + a terse
    // description, with no parameter summaries or input schemas. This is the
    // cheap, non-opaque counterpart to the compact catalog: the agent can see
    // the full set of tools for a small token cost, then search/load the few it
    // actually needs. A query switches to ranked search with parameter details.
    const listAll = query.length === 0;
    const includeSchemas = !listAll && parseBoolean(args.includeSchemas);
    const readOnlyOnly = parseBoolean(args.readOnlyOnly);
    const limit = parseLimit(args.limit, options.defaultLimit ?? DEFAULT_LIMIT, options.maxLimit ?? MAX_LIMIT);
    const cacheKey = normalizeToolSearchCacheKey({
        query,
        limit,
        includeSchemas,
        readOnlyOnly,
    });
    const runCtx = getRequestRunContext();
    const priorSearch = includeSchemas
        ? undefined
        : runCtx?.toolSearchReads?.[cacheKey];
    if (priorSearch) {
        return {
            query,
            totalTools: priorSearch.totalTools,
            count: priorSearch.resultNames.length,
            repeated: true,
            message: "This exact tool-search query already ran in this agent run. Use the previously returned schemas/details instead of searching again.",
            results: priorSearch.resultNames.map((name) => ({
                name,
                kind: parseMcpToolName(name) ? "mcp" : "action",
                score: 0,
                callable: registry[name]?.allowInPlanMode !== false,
                planAvailability: getPlanAvailability(name, registry[name]),
                description: "Already returned by an earlier identical tool-search call.",
                parameters: [],
            })),
        };
    }
    const queryTokens = tokenize(query);
    const candidates = [];
    let totalTools = 0;
    for (const [name, entry] of Object.entries(registry)) {
        if (!entry?.tool || name === TOOL_SEARCH_ACTION_NAME)
            continue;
        if (isActionHiddenFromEveryAgentSurface(entry))
            continue;
        if (name.startsWith("mcp__") && !isMcpToolAllowedForRequest(name)) {
            continue;
        }
        const description = normalizeWhitespace(entry.tool.description ?? "");
        const parsedMcp = parseMcpToolName(name);
        const kind = parsedMcp ? "mcp" : "action";
        const source = parsedMcp?.serverId;
        const callable = entry.allowInPlanMode !== false;
        const planAvailability = getPlanAvailability(name, entry);
        // Conditional policies still need discovery: MCP tools and provider/web
        // actions classify the arguments at call time. Bash is marked conditional
        // for Plan mode, but the orchestration bridge intentionally does not expose
        // shell execution, so do not advertise it as a child-call candidate.
        if (readOnlyOnly &&
            planAvailability !== "read" &&
            (planAvailability !== "conditional" || name === "bash")) {
            continue;
        }
        totalTools++;
        if (listAll) {
            candidates.push({
                name,
                kind,
                ...(source ? { source } : {}),
                description: truncate(description, 140),
                score: 0,
                callable,
                planAvailability,
                parameters: [],
            });
            continue;
        }
        const parameters = summarizeParameters(entry.tool.parameters);
        const score = scoreTool({
            query,
            queryTokens,
            name,
            source,
            description,
            parameters,
            kind,
        });
        if (score <= 0)
            continue;
        candidates.push({
            name,
            kind,
            ...(source ? { source } : {}),
            description,
            score,
            callable,
            planAvailability,
            parameters,
            ...(includeSchemas ? { inputSchema: entry.tool.parameters ?? {} } : {}),
        });
    }
    if (listAll) {
        candidates.sort((a, b) => a.name.localeCompare(b.name));
        const result = {
            query,
            totalTools,
            count: candidates.length,
            message: 'Menu mode lists tool names only; it does not load schemas for calling. Before invoking a tool found here, call tool-search again with a specific query such as the tool name or capability (for example, { "query": "hubspot-deals" }).',
            results: candidates,
        };
        rememberToolSearchResult(cacheKey, result);
        return result;
    }
    candidates.sort((a, b) => {
        if (b.score !== a.score)
            return b.score - a.score;
        return a.name.localeCompare(b.name);
    });
    const result = {
        query,
        totalTools,
        count: Math.min(candidates.length, limit),
        results: candidates.slice(0, limit),
    };
    if (!includeSchemas)
        rememberToolSearchResult(cacheKey, result);
    return result;
}
const PLAN_MODE_BLOCKED_DISCOVERY_TOOLS = new Set([
    "refresh-screen",
    "set-search-params",
    "set-url-path",
]);
function getPlanAvailability(name, entry) {
    if (!entry || entry.allowInPlanMode === false)
        return "act-only";
    if (PLAN_MODE_BLOCKED_DISCOVERY_TOOLS.has(name))
        return "act-only";
    if (name === "bash")
        return "conditional";
    if (typeof entry.planMode?.effect === "function")
        return "conditional";
    if (entry.planMode?.effect === "read")
        return "read";
    if (entry.planMode?.effect === "write" ||
        entry.planMode?.effect === "unknown") {
        return "act-only";
    }
    return entry.readOnly === true ? "read" : "act-only";
}
function normalizeToolSearchCacheKey(options) {
    return JSON.stringify({
        query: options.query.trim().toLowerCase(),
        limit: options.limit,
        includeSchemas: options.includeSchemas,
        readOnlyOnly: options.readOnlyOnly,
    });
}
function rememberToolSearchResult(cacheKey, result) {
    const runCtx = getRequestRunContext();
    if (!runCtx)
        return;
    const reads = (runCtx.toolSearchReads ??= {});
    reads[cacheKey] = {
        totalTools: result.totalTools,
        resultNames: result.results.map((item) => item.name),
    };
}
function truncate(value, max) {
    if (value.length <= max)
        return value;
    return `${value.slice(0, max - 1).trimEnd()}…`;
}
function parseLimit(value, fallback, max) {
    const n = typeof value === "number"
        ? value
        : typeof value === "string" && value.trim()
            ? Number(value)
            : fallback;
    if (!Number.isFinite(n) || n <= 0)
        return fallback;
    return Math.max(1, Math.min(max, Math.floor(n)));
}
function parseBoolean(value) {
    if (typeof value === "boolean")
        return value;
    if (typeof value !== "string")
        return false;
    const normalized = value.trim().toLowerCase();
    return normalized === "true" || normalized === "1" || normalized === "yes";
}
function summarizeParameters(schema) {
    if (!schema || typeof schema !== "object")
        return [];
    const obj = schema;
    const properties = obj.properties;
    if (!properties || typeof properties !== "object")
        return [];
    const required = new Set(Array.isArray(obj.required)
        ? obj.required.filter((value) => typeof value === "string")
        : []);
    return Object.entries(properties).map(([name, raw]) => {
        const prop = raw && typeof raw === "object" ? raw : {};
        const enumValues = Array.isArray(prop.enum)
            ? prop.enum.map((value) => String(value)).slice(0, 20)
            : undefined;
        return {
            name,
            type: summarizeType(prop.type),
            required: required.has(name),
            description: typeof prop.description === "string"
                ? normalizeWhitespace(prop.description)
                : undefined,
            ...(enumValues && enumValues.length > 0 ? { enum: enumValues } : {}),
        };
    });
}
function summarizeType(value) {
    if (typeof value === "string")
        return value;
    if (Array.isArray(value)) {
        const parts = value.filter((v) => typeof v === "string");
        return parts.length > 0 ? parts.join(" | ") : undefined;
    }
    return undefined;
}
function scoreTool(input) {
    if (input.queryTokens.length === 0)
        return 1;
    const name = searchableText(input.name);
    const source = searchableText(input.source ?? "");
    const description = searchableText(input.description);
    const params = searchableText(input.parameters
        .map((p) => `${p.name} ${p.type ?? ""} ${p.description ?? ""}`)
        .join(" "));
    const all = `${name} ${source} ${description} ${params} ${input.kind}`;
    const phrase = searchableText(input.query);
    let score = 0;
    if (name.includes(phrase))
        score += 14;
    if (source && source.includes(phrase))
        score += 10;
    if (description.includes(phrase))
        score += 8;
    if (params.includes(phrase))
        score += 5;
    for (const token of input.queryTokens) {
        if (name.split(" ").includes(token))
            score += 9;
        else if (name.includes(token))
            score += 6;
        if (source) {
            if (source.split(" ").includes(token))
                score += 6;
            else if (source.includes(token))
                score += 3;
        }
        if (description.includes(token))
            score += 3;
        if (params.includes(token))
            score += 2;
        if (all.includes(token))
            score += 1;
    }
    return score;
}
function tokenize(value) {
    const seen = new Set();
    for (const token of searchableText(value).split(" ")) {
        if (token.length > 0)
            seen.add(token);
    }
    return Array.from(seen);
}
function searchableText(value) {
    return value
        .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, " ")
        .trim();
}
function normalizeWhitespace(value) {
    return value.replace(/\s+/g, " ").trim();
}
